const j = $input.item.json;
const bin = $input.item.binary || {};
const key = Object.keys(bin)[0];
if (!key) throw new Error('No CV file uploaded');
const pick = (...k) => { for (const x of k) if (j[x] !== undefined && j[x] !== null && j[x] !== '') return String(j[x]).trim(); return ''; };
return { json: {
  source: 'form',
  name: pick('Full name', 'Name', 'name'),
  email: pick('Email', 'email').toLowerCase(),
  location: pick('Location', 'location'),
  note: pick('Note to the hiring team', 'Note', 'note'),
  cv_filename: bin[key].fileName || 'cv.pdf'
}, binary: { cv: bin[key] } };

// One item per PDF attachment. Emails without a PDF are skipped.
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const from = String(j.from || '');
  const m = from.match(/^\s*"?([^"<]*)"?\s*<([^>]+)>/);
  const name = m ? m[1].trim() : '';
  const email = (m ? m[2] : from).trim().toLowerCase();
  for (const [key, b] of Object.entries(item.binary || {})) {
    const isPdf = (b.mimeType || '').includes('pdf') || /\.pdf$/i.test(b.fileName || '');
    if (!isPdf) continue;
    out.push({ json: {
      source: 'email', name, email, location: '',
      note: String(j.subject || '') + ' ' + String(j.textPlain || j.text || '').slice(0, 500),
      cv_filename: b.fileName || 'cv.pdf'
    }, binary: { cv: b } });
  }
}
return out;

const src = $('From Form').isExecuted ? $('From Form').item.json : $('From Email').item.json;
const raw = typeof $json.text === 'string' ? $json.text : '';
const cv_text = raw.replace(/\u0000/g, '').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim().slice(0, 12000);
return { json: {
  candidate_id: 'C-' + Date.now() + '-' + Math.floor(Math.random() * 1000),
  received_at: new Date().toISOString(),
  ...src,
  cv_readable: cv_text.length >= 200,
  cv_text: cv_text.length >= 200 ? cv_text : 'CV TEXT NOT READABLE (scanned or empty PDF)'
}};

