const ai = $json.output || {};
const c = $('Job Profile').item.json;
const n = v => Math.max(0, Math.min(100, Number(v) || 0));
const arr = v => Array.isArray(v) ? v : [];
const must = arr(ai.must_haves);
const missing = must.filter(m => m && m.met === false);
const met = must.filter(m => m && m.met === true);
const flags = arr(ai.red_flags);

// Final score is code, not AI. Same sub scores in, same score out.
let s = Math.round(n(ai.skills_score) * 0.45 + n(ai.experience_score) * 0.35 + n(ai.location_score) * 0.20);
s -= 15 * missing.length;                                   // each missed must-have
if (Number(ai.years_experience) < Number(c.min_years)) s -= 10;  // below minimum years
if (flags.length >= 2) s -= 10;                              // 2+ red flags
s = Math.max(0, Math.min(100, s));

const tier = (s >= 75 && missing.length === 0) ? 'strong' : s >= 55 ? 'possible' : 'reject';
const status = (!c.cv_readable || ai.confidence === 'low') ? 'needs_review' : 'screened';

return { json: { ...c, ...ai,
  name: c.name || ai.candidate_name || '',
  email: c.email || ai.email_in_cv || '',
  location: c.location || ai.location || '',
  skills_score: n(ai.skills_score), experience_score: n(ai.experience_score), location_score: n(ai.location_score),
  final_score: s, tier, status,
  must_haves_met: met.length + '/' + must.length,
  must_haves_missing: missing.map(m => m.requirement).join(' | '),
  skills_matched: arr(ai.skills_matched).join(', '),
  skills_missing: arr(ai.skills_missing).join(', '),
  nice_to_haves_matched: arr(ai.nice_to_haves_matched).join(', '),
  strengths: arr(ai.strengths).join(' | '),
  concerns: arr(ai.concerns).join(' | '),
  red_flags: flags.join(' | ')
}};

const r = $json;
const cols = ["candidate_id", "received_at", "source", "job_id", "job_title", "name", "email", "location", "cv_filename", "current_title", "years_experience", "skills_matched", "skills_missing", "nice_to_haves_matched", "must_haves_met", "must_haves_missing", "skills_score", "experience_score", "location_score", "final_score", "tier", "summary", "strengths", "concerns", "red_flags", "confidence", "status", "ack_sent_at", "shortlisted_at", "notes"];
const row = {};
for (const c of cols) row[c] = r[c] !== undefined ? r[c] : '';
row.ack_sent_at = '';
row.shortlisted_at = '';
return { json: row };

